        <div className="rounded-xl border border-sidebar-border bg-sidebar-accent/50 p-3"><div className="mb-2 flex items-center gap-2 text-[11px] font-bold"><span className={`h-2 w-2 rounded-full ${health.isError ? 'bg-red-400' : health.isLoading ? 'bg-amber-400' : 'bg-emerald-400'}`} />{health.isError ? 'Radar offline' : health.isLoading ? 'Connecting' : 'Radar online'}</div><p className="text-[11px] leading-relaxed text-sidebar-foreground/50">Watching public career pages for the next right move.</p></div>
