function JobRow({ job }: { job: any }) {
  return <Link href={`/jobs/${job.id}`} className="group flex items-center gap-3 border-b border-border px-4 py-4 last:border-0 hover:bg-secondary/35 sm:gap-4" data-testid={`row-job-${job.id}`}><div className="flex h-9 w-9 shrink-0 items-center justify-center rounded-lg bg-primary text-[11px] font-bold text-primary-foreground">{initials(job.company)}</div><div className="min-w-0 flex-1"><div className="truncate text-sm font-bold group-hover:text-emerald-700">{job.title}</div><div className="mt-1 flex flex-wrap items-center gap-x-2 gap-y-1 text-xs text-muted-foreground"><span>{job.company}</span><span className="text-border">•</span><span>{job.location || 'Location flexible'}</span><span className="hidden text-border sm:inline">•</span><span className="hidden sm:inline">{formatRelative(job.firstSeenAt || job.postedDate)}</span></div></div><div className="hidden items-center gap-3 sm:flex"><span className="text-xs text-muted-foreground">{job.workplaceType}</span><Score score={job.score} compact /><ArrowUpRight size={15} className="text-muted-foreground transition-transform group-hover:-translate-y-0.5 group-hover:translate-x-0.5" /></div></Link>;
}
function Dashboard() {
  const q = useGetDashboard();
  const dashboard: any = q.data;
  if (q.isLoading) return <><PageTitle eyebrow="Daily brief" title="Your signal desk" detail="A tight view of what moved since your last check." /><LoadingBlock /></>;
  if (q.isError || !dashboard) return <><PageTitle eyebrow="Daily brief" title="Your signal desk" detail="A tight view of what moved since your last check." /><QueryError retry={() => q.refetch()} /></>;
  const stats = dashboard.stats || {};
  const health = dashboard.sourceHealth || [];
  return <div className="rise"><PageTitle eyebrow="Daily brief · refreshed just now" title="Your signal desk" detail="The roles worth your attention, without the scroll." action={<Link href="/jobs?status=matched" className="btn btn-accent" data-testid="link-view-matches"><Sparkles size={15} />Review matches <ArrowUpRight size={14} /></Link>} />
    <div className="mb-7 grid grid-cols-2 gap-3 lg:grid-cols-5">{[['companies', stats.companies, 'companies watched', Building2], ['activeSources', stats.activeSources, 'sources live', Globe2], ['newJobs', stats.newJobs, 'new this week', Zap], ['matchedJobs', stats.matchedJobs, 'high-signal matches', Sparkles], ['notifiedJobs', stats.notifiedJobs, 'alerts sent', Bell]].map(([key, value, label, Icon]: any, i) => <div className={`card p-4 ${i === 3 ? 'border-accent/60 bg-accent/10' : ''}`} key={key} data-testid={`stat-${key}`}><div className="mb-4 flex items-center justify-between"><span className="mono text-[10px] font-bold text-muted-foreground">{String(label).toUpperCase()}</span><Icon size={16} className={i === 3 ? 'text-amber-700' : 'text-muted-foreground'} /></div><div className="mono text-2xl font-bold tracking-tight">{value ?? '—'}</div><div className="mt-1 text-[11px] text-muted-foreground">{i === 2 ? 'since last scan' : i === 3 ? 'above your threshold' : 'in your workspace'}</div></div>)}</div>
    <div className="grid gap-6 xl:grid-cols-[1.45fr_.85fr]"><section className="card overflow-hidden"><div className="flex items-center justify-between border-b border-border px-4 py-4 sm:px-5"><div><h2 className="font-bold">Recent high-match roles</h2><p className="mt-1 text-xs text-muted-foreground">Sorted by fit, then freshness</p></div><Link href="/jobs" className="text-xs font-bold text-emerald-700 hover:underline" data-testid="link-all-jobs">All jobs <ArrowUpRight size={13} className="inline" /></Link></div>{dashboard.recentMatches?.length ? dashboard.recentMatches.slice(0, 6).map((job: any) => <JobRow key={job.id} job={job} />) : <EmptyState title="No matches yet" detail="Run a scan after adding a few career sources." action={<Link href="/sources" className="btn btn-primary" data-testid="link-add-source-empty">Add a source</Link>} />}</section>
      <section className="card overflow-hidden"><div className="flex items-center justify-between border-b border-border px-5 py-4"><div><h2 className="font-bold">Source pulse</h2><p className="mt-1 text-xs text-muted-foreground">The health of your signal</p></div><Link href="/source-health" className="text-muted-foreground hover:text-foreground" data-testid="link-source-health"><Activity size={17} /></Link></div><div className="divide-y divide-border">{health.slice(0, 5).map((source: any) => <div className="flex items-center gap-3 px-5 py-3.5" key={source.id} data-testid={`health-row-${source.id}`}><div className={`flex h-8 w-8 items-center justify-center rounded-md ${source.status === 'healthy' ? 'bg-emerald-100 text-emerald-700' : source.status === 'failed' ? 'bg-red-100 text-red-700' : 'bg-amber-100 text-amber-700'}`}><Globe2 size={15} /></div><div className="min-w-0 flex-1"><div className="truncate text-xs font-bold">{source.companyName}</div><div className="mt-0.5 truncate text-[11px] text-muted-foreground">{source.name}</div></div><div className="text-right"><StatusPill status={source.status} /><div className="mono mt-1 text-[9px] text-muted-foreground">{formatRelative(source.lastFetch)}</div></div></div>)}{!health.length && <div className="p-8 text-center text-sm text-muted-foreground">No sources connected.</div>}</div></section></div>
    <div className="mt-6 card flex flex-col items-start gap-4 border-primary/10 bg-primary p-5 text-primary-foreground sm:flex-row sm:items-center"><div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-lg bg-accent text-primary"><Gauge size={20} /></div><div className="flex-1"><div className="text-sm font-bold">Your radar is tuned to clarity.</div><div className="mt-1 text-xs text-primary-foreground/60">Adjust scoring weights and keyword rules when your search evolves.</div></div><Link href="/matching" className="btn border border-primary-foreground/20 bg-primary-foreground/10 text-primary-foreground hover:bg-primary-foreground/15" data-testid="link-tune-matching">Tune matching <ChevronRight size={14} /></Link></div>
  </div>;
}

function CompanyModal({ company, close }: { company?: any; close: () => void }) {
  const [name, setName] = useState(company?.name || '');
  const [domain, setDomain] = useState(company?.domain || '');
  const qc = useQueryClient(); const create = useCreateCompany(); const update = useUpdateCompany();
  const submit = (e: React.FormEvent) => {
  e.preventDefault();

  console.log("ADD COMPANY SUBMIT FIRED");

  const done = () => {
    console.log("ADD COMPANY SUCCESS");
    qc.invalidateQueries({ queryKey: getListCompaniesQueryKey() });
    close();
  };

  if (company) {
    update.mutate(
      { id: company.id, data: { name, domain } },
      {
        onSuccess: done,
        onError: (error) => {
          console.error("UPDATE COMPANY ERROR:", error);
        },
      }
    );
  } else {
    create.mutate(
      { data: { name, domain } },
      {
        onSuccess: done,
        onError: (error) => {
          console.error("CREATE COMPANY ERROR:", error);
        },
      }
    );
  }
};
  return <Modal title={company ? 'Edit company' : 'Add company'} close={close}><form className="space-y-4" onSubmit={submit}><div><label className="label" htmlFor="company-name">Company name</label><input id="company-name" className="field" value={name} onChange={(e) => setName(e.target.value)} placeholder="e.g. Linear" required data-testid="input-company-name" /></div><div><label className="label" htmlFor="company-domain">Career domain</label><input id="company-domain" className="field" value={domain} onChange={(e) => setDomain(e.target.value)} placeholder="linear.app" required data-testid="input-company-domain" /></div><div className="flex justify-end gap-2 pt-2"><button type="button" className="btn btn-ghost" onClick={close} data-testid="button-cancel-company">Cancel</button><button className="btn btn-primary" disabled={create.isPending || update.isPending} data-testid="button-save-company">{create.isPending || update.isPending ? 'Saving…' : company ? 'Save changes' : 'Add company'}</button></div></form></Modal>;
}
function Companies() {
  const q = useListCompanies(); const companies: any[] = q.data || []; const [modal, setModal] = useState<any>(null); const [search, setSearch] = useState(''); const qc = useQueryClient(); const del = useDeleteCompany(); const update = useUpdateCompany();
  const filtered = companies.filter((c) => `${c.name} ${c.domain}`.toLowerCase().includes(search.toLowerCase()));
  const toggle = (c: any) => update.mutate({ id: c.id, data: { enabled: !c.enabled } }, { onSuccess: () => qc.invalidateQueries({ queryKey: getListCompaniesQueryKey() }) });
  if (q.isLoading) return <><PageTitle eyebrow="Monitor / companies" title="Companies" detail="The organizations your radar keeps in view." /><LoadingBlock lines={5} /></>;
  if (q.isError) return <><PageTitle eyebrow="Monitor / companies" title="Companies" detail="The organizations your radar keeps in view." /><QueryError retry={() => q.refetch()} /></>;
  return <div className="rise"><PageTitle eyebrow="Monitor / companies" title="Companies" detail={`${companies.length} organizations in your watchlist.`} action={<button className="btn btn-primary" onClick={() => setModal('new')} data-testid="button-add-company"><Plus size={15} />Add company</button>} /><div className="mb-5 flex flex-col gap-3 sm:flex-row"><div className="relative max-w-sm flex-1"><Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground" /><input className="field pl-9" value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Search companies…" data-testid="input-search-companies" /></div><div className="mono flex items-center gap-2 text-[10px] uppercase tracking-wider text-muted-foreground"><span className="h-2 w-2 rounded-full bg-emerald-500" />{companies.filter((c) => c.enabled).length} active</div></div>{!filtered.length ? <EmptyState title="Your watchlist is clear" detail={companies.length ? 'No company matches that search.' : 'Add a company to start watching public career pages.'} action={!companies.length && <button className="btn btn-primary" onClick={() => setModal('new')} data-testid="button-add-company-empty"><Plus size={14} />Add first company</button>} /> : <div className="grid gap-3 md:grid-cols-2 xl:grid-cols-3">{filtered.map((c) => <div className="card group p-4 transition-transform hover:-translate-y-0.5" key={c.id} data-testid={`card-company-${c.id}`}><div className="flex items-start justify-between"><div className="flex items-center gap-3"><div className="flex h-11 w-11 items-center justify-center rounded-xl text-sm font-bold" style={{ backgroundColor: `${c.color || '#d9c16f'}33`, color: c.color || '#8b6f18' }}>{c.initials || initials(c.name)}</div><div><h2 className="font-bold">{c.name}</h2><div className="mt-0.5 flex items-center gap-1 text-xs text-muted-foreground"><Globe2 size={11} />{c.domain}</div></div></div><button className="rounded-md p-1.5 text-muted-foreground hover:bg-muted" onClick={() => setModal(c)} data-testid={`button-edit-company-${c.id}`}><MoreHorizontal size={17} /></button></div><div className="mt-5 flex items-end justify-between border-t border-border pt-3"><div className="flex gap-5"><div><div className="mono text-lg font-bold">{c.sourceCount ?? 0}</div><div className="text-[10px] uppercase tracking-wider text-muted-foreground">sources</div></div><div><div className="mono text-lg font-bold">{c.jobCount ?? 0}</div><div className="text-[10px] uppercase tracking-wider text-muted-foreground">jobs found</div></div></div><div className="flex items-center gap-2"><button className={`relative h-6 w-10 rounded-full transition-colors ${c.enabled ? 'bg-emerald-600' : 'bg-muted'}`} onClick={() => toggle(c)} aria-label={`Toggle ${c.name}`} data-testid={`button-toggle-company-${c.id}`}><span className={`absolute top-1 h-4 w-4 rounded-full bg-card transition-transform ${c.enabled ? 'left-5' : 'left-1'}`} /></button><button className="rounded-md p-1.5 text-muted-foreground hover:bg-red-50 hover:text-destructive" onClick={() => { if (window.confirm(`Remove ${c.name} from your watchlist?`)) del.mutate({ id: c.id }, { onSuccess: () => qc.invalidateQueries({ queryKey: getListCompaniesQueryKey() }) }); }} data-testid={`button-delete-company-${c.id}`}><Trash2 size={14} /></button></div></div></div>)}</div>}{modal && <CompanyModal company={modal === 'new' ? undefined : modal} close={() => setModal(null)} />}</div>;
}

function SourceModal({ source, companies, close }: { source?: any; companies: any[]; close: () => void }) {
  const [companyId, setCompanyId] = useState(source?.companyId || companies[0]?.id || ''); const [name, setName] = useState(source?.name || ''); const [type, setType] = useState(source?.type || 'GREENHOUSE_API'); const [url, setUrl] = useState(source?.url || '');
  const qc = useQueryClient(); const create = useCreateSource(); const update = useUpdateSource();
  const submit = (e: React.FormEvent) => { e.preventDefault(); const done = () => { qc.invalidateQueries({ queryKey: getListSourcesQueryKey() }); qc.invalidateQueries({ queryKey: getListCompaniesQueryKey() }); close(); }; source ? update.mutate({ id: source.id, data: { name, url } }, { onSuccess: done }) : create.mutate({ data: { companyId, name, type, url } }, { onSuccess: done }); };
  if (!source && !companies.length) return <Modal title="Add source" close={close}><div className="space-y-4"><p className="text-sm text-muted-foreground">A source belongs to a company. Add a company first, then return here to connect its career page or public job API.</p><div className="flex justify-end gap-2"><button type="button" className="btn btn-ghost" onClick={close} data-testid="button-cancel-source">Cancel</button><Link href="/companies" className="btn btn-primary" onClick={close} data-testid="link-add-company-first"><Plus size={15} />Add company first</Link></div></div></Modal>;
  return <Modal title={source ? 'Edit source' : 'Add source'} close={close}><form className="space-y-4" onSubmit={submit}>{!source && <div><label className="label" htmlFor="source-company">Company</label><select id="source-company" className="field" value={companyId} onChange={(e) => setCompanyId(e.target.value)} required data-testid="select-source-company">{companies.map((c) => <option value={c.id} key={c.id}>{c.name}</option>)}</select></div>}<div><label className="label" htmlFor="source-name">Source name</label><input id="source-name" className="field" value={name} onChange={(e) => setName(e.target.value)} placeholder="Main careers page" required data-testid="input-source-name" /></div>{!source && <div><label className="label" htmlFor="source-type">Connector</label><select id="source-type" className="field" value={type} onChange={(e) => { const next = e.target.value; setType(next); if (next === 'DELOITTE_USI') setUrl('https://usijobs.deloitte.com/careersUSI/SearchJobs'); }} data-testid="select-source-type"><option value="GREENHOUSE_API">Greenhouse API</option><option value="DELOITTE_USI">Deloitte USI careers</option><option value="LEVER_API">Lever API</option><option value="STRUCTURED_HTML">Structured HTML</option><option value="GENERIC_HTML">Generic HTML</option></select></div>}<div><label className="label" htmlFor="source-url">Source URL</label><input id="source-url" type="url" className="field" value={url} onChange={(e) => setUrl(e.target.value)} placeholder="https://…" required data-testid="input-source-url" /></div>{type === 'DELOITTE_USI' && <p className="text-xs text-muted-foreground">Uses Deloitte USI’s official public job search and creates direct “Apply” links for every role.</p>}<div className="flex justify-end gap-2 pt-2"><button type="button" className="btn btn-ghost" onClick={close} data-testid="button-cancel-source">Cancel</button><button className="btn btn-primary" disabled={create.isPending || update.isPending} data-testid="button-save-source">{create.isPending || update.isPending ? 'Saving…' : source ? 'Save changes' : 'Add source'}</button></div></form></Modal>;
}
function SourceCard({ source, onEdit }: { source: any; onEdit: () => void }) {
  const qc = useQueryClient(); const scan = useScanSource(); const del = useDeleteSource(); const update = useUpdateSource();
  return <div className="card p-4" data-testid={`card-source-${source.id}`}><div className="flex items-start gap-3"><div className={`flex h-9 w-9 shrink-0 items-center justify-center rounded-lg ${source.status === 'healthy' ? 'bg-emerald-100 text-emerald-700' : source.status === 'failed' ? 'bg-red-100 text-red-700' : 'bg-amber-100 text-amber-700'}`}><Globe2 size={16} /></div><div className="min-w-0 flex-1"><div className="flex items-start justify-between gap-3"><div><h2 className="truncate text-sm font-bold">{source.name}</h2><div className="mt-0.5 text-xs text-muted-foreground">{source.companyName}</div></div><StatusPill status={source.status} /></div><a href={source.url} target="_blank" rel="noreferrer" className="mt-3 block truncate text-[11px] text-emerald-700 hover:underline" data-testid={`link-source-url-${source.id}`}>{source.url} <ExternalLink size={10} className="inline" /></a><div className="mt-4 grid grid-cols-3 gap-2 border-t border-border pt-3"><div><div className="mono text-sm font-bold">{source.jobsFetched ?? 0}</div><div className="text-[10px] text-muted-foreground">jobs / last fetch</div></div><div><div className="mono text-sm font-bold">{source.failureCount ?? 0}</div><div className="text-[10px] text-muted-foreground">failures</div></div><div><div className="mono text-sm font-bold">{formatRelative(source.lastFetch)}</div><div className="text-[10px] text-muted-foreground">last run</div></div></div></div></div>{source.lastError && <div className="mt-3 rounded-md bg-red-50 p-2 text-[11px] text-red-700"><CircleAlert size={12} className="mr-1 inline" />{source.lastError}</div>}<div className="mt-4 flex justify-end gap-1 border-t border-border pt-3"><button className="btn btn-ghost px-2.5 py-1.5 text-xs" onClick={() => scan.mutate({ id: source.id }, { onSuccess: () => { qc.invalidateQueries({ queryKey: getListSourcesQueryKey() }); qc.invalidateQueries({ queryKey: getListJobsQueryKey() }); } })} disabled={scan.isPending} data-testid={`button-scan-source-${source.id}`}><RefreshCw size={13} className={scan.isPending ? 'animate-spin' : ''} />Scan</button><button className={`btn px-2.5 py-1.5 text-xs ${source.enabled ? 'btn-ghost' : 'btn-accent'}`} onClick={() => update.mutate({ id: source.id, data: { enabled: !source.enabled } }, { onSuccess: () => qc.invalidateQueries({ queryKey: getListSourcesQueryKey() }) })} data-testid={`button-toggle-source-${source.id}`}>{source.enabled ? 'Pause' : 'Enable'}</button><button className="btn btn-ghost px-2.5 py-1.5 text-xs" onClick={onEdit} data-testid={`button-edit-source-${source.id}`}>Edit</button><button className="btn btn-danger px-2.5 py-1.5 text-xs" onClick={() => { if (window.confirm(`Delete ${source.name}?`)) del.mutate({ id: source.id }, { onSuccess: () => qc.invalidateQueries({ queryKey: getListSourcesQueryKey() }) }); }} data-testid={`button-delete-source-${source.id}`}><Trash2 size={13} /></button></div></div>;
}
function Sources({ healthOnly = false }: { healthOnly?: boolean }) {
  const q = useListSources(); const c = useListCompanies(); const sources: any[] = q.data || []; const [modal, setModal] = useState<any>(null); const [filter, setFilter] = useState('all');
  const visible = sources.filter((s) => filter === 'all' || s.status === filter);
  if (q.isLoading || c.isLoading) return <><PageTitle eyebrow={healthOnly ? 'Tune / source health' : 'Monitor / sources'} title={healthOnly ? 'Source health' : 'Sources'} detail="Keep the collection layer honest." /><LoadingBlock lines={5} /></>;
  if (q.isError || c.isError) return <QueryError retry={() => { q.refetch(); c.refetch(); }} />;
  return <div className="rise"><PageTitle eyebrow={healthOnly ? 'Tune / source health' : 'Monitor / sources'} title={healthOnly ? 'Source health' : 'Sources'} detail={healthOnly ? 'Fetch status, failure patterns, and the next thing to fix.' : 'Career pages and APIs feeding your radar.'} action={!healthOnly && <button className="btn btn-primary" onClick={() => setModal('new')} data-testid="button-add-source"><Plus size={15} />Add source</button>} /><div className="mb-5 flex flex-wrap items-center gap-2"><Filter size={15} className="text-muted-foreground" />{['all', 'healthy', 'warning', 'failed', 'never_run'].map((item) => <button key={item} className={`rounded-full border px-3 py-1.5 text-xs font-bold transition-colors ${filter === item ? 'border-primary bg-primary text-primary-foreground' : 'border-border bg-card text-muted-foreground hover:bg-muted'}`} onClick={() => setFilter(item)} data-testid={`button-filter-source-${item}`}>{item === 'all' ? 'All sources' : item.replace('_', ' ')}</button>)}<span className="ml-auto mono text-[10px] text-muted-foreground">{visible.length} / {sources.length}</span></div>{!visible.length ? <EmptyState title="No sources in this lane" detail={sources.length ? 'Try another health filter.' : 'Add a source to start collecting roles.'} /> : <div className="grid gap-4 lg:grid-cols-2">{visible.map((source) => <SourceCard key={source.id} source={source} onEdit={() => setModal(source)} />)}</div>}{modal && <SourceModal source={modal === 'new' ? undefined : modal} companies={c.data || []} close={() => setModal(null)} />}</div>;
}

function Jobs() {
  const [search, setSearch] = useState(''); const [status, setStatus] = useState('all'); const [workplace, setWorkplace] = useState(''); const [location, setLocation] = useState('');
  const q = useListJobs({ search: search || undefined, status: status as any, location: location || undefined, workplaceType: workplace || undefined }); const jobs: any[] = q.data || [];
  return <div className="rise"><PageTitle eyebrow="Monitor / jobs" title="Discovered jobs" detail={`${jobs.length} roles returned by your current filters.`} /><div className="card mb-5 p-3"><div className="flex flex-col gap-3 lg:flex-row"><div className="relative flex-1"><Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground" /><input className="field pl-9" placeholder="Search title, company, skills…" value={search} onChange={(e) => setSearch(e.target.value)} data-testid="input-search-jobs" /></div><input className="field lg:w-40" placeholder="Location e.g. Pune" value={location} onChange={(e) => setLocation(e.target.value)} data-testid="input-filter-location" /><select className="field lg:w-40" value={status} onChange={(e) => setStatus(e.target.value)} data-testid="select-job-status"><option value="all">All jobs</option><option value="matched">Matched only</option><option value="new">New only</option><option value="notified">Notified</option></select><select className="field lg:w-40" value={workplace} onChange={(e) => setWorkplace(e.target.value)} data-testid="select-job-workplace"><option value="">Any workplace</option><option value="Remote">Remote</option><option value="Hybrid">Hybrid</option><option value="On-site">On-site</option></select></div></div>{q.isLoading ? <LoadingBlock lines={6} /> : q.isError ? <QueryError retry={() => q.refetch()} /> : !jobs.length ? <EmptyState title="No roles match" detail="Try widening the search or run a fresh source scan." action={<Link href="/sources" className="btn btn-primary" data-testid="link-scan-sources-empty">Check sources</Link>} /> : <div className="card overflow-hidden">{jobs.map((job) => <JobRow key={job.id} job={job} />)}</div>}</div>;
}

function JobDetail() {
  const { id } = useParams<{ id: string }>(); const q = useGetJob(id || '', { query: { enabled: Boolean(id), queryKey: getGetJobQueryKey(id || '') } }); const job: any = q.data;
  if (q.isLoading) return <><Link href="/jobs" className="mb-6 inline-flex items-center gap-2 text-sm font-bold text-muted-foreground" data-testid="link-back-jobs"><ArrowLeft size={15} />Back to jobs</Link><LoadingBlock lines={5} /></>;
  if (q.isError || !job) return <><Link href="/jobs" className="mb-6 inline-flex items-center gap-2 text-sm font-bold text-muted-foreground" data-testid="link-back-jobs"><ArrowLeft size={15} />Back to jobs</Link><QueryError retry={() => q.refetch()} /></>;
  const breakdown = job.breakdown || {};
  return <div className="rise"><Link href="/jobs" className="mb-6 inline-flex items-center gap-2 text-sm font-bold text-muted-foreground hover:text-foreground" data-testid="link-back-jobs"><ArrowLeft size={15} />Back to jobs</Link><div className="grid gap-6 xl:grid-cols-[1.45fr_.75fr]"><main><div className="card p-5 sm:p-7"><div className="flex flex-col gap-5 sm:flex-row sm:items-start"><div className="flex h-14 w-14 shrink-0 items-center justify-center rounded-2xl bg-primary text-lg font-bold text-primary-foreground">{initials(job.company)}</div><div className="min-w-0 flex-1"><div className="mono mb-2 text-[10px] uppercase tracking-[.16em] text-muted-foreground">{job.department || 'Role'} · {job.employmentType || 'Full time'}</div><h1 className="text-2xl font-bold tracking-tight sm:text-3xl">{job.title}</h1><div className="mt-2 flex flex-wrap items-center gap-2 text-sm text-muted-foreground"><span className="font-bold text-foreground">{job.company}</span><span>·</span><span>{job.location || 'Location flexible'}</span><span>·</span><span>{job.workplaceType}</span></div></div><Score score={job.score} /></div><div className="mt-7 flex flex-wrap gap-2 border-t border-border pt-5"><a href={job.applicationUrl} target="_blank" rel="noreferrer" className="btn btn-accent" data-testid="link-apply-job"><ExternalLink size={15} />Open application</a><a href={job.sourceUrl} target="_blank" rel="noreferrer" className="btn btn-ghost" data-testid="link-view-source"><Eye size={15} />View source</a></div></div><article className="card mt-5 p-5 sm:p-7"><div className="mb-5 flex items-center justify-between"><h2 className="font-bold">Normalized description</h2><span className="mono text-[10px] text-muted-foreground">FIRST SEEN {formatDate(job.firstSeenAt)}</span></div><div className="prose prose-sm max-w-none text-foreground/80" dangerouslySetInnerHTML={{ __html: job.description || '<p>No description was provided by the source.</p>' }} /></article></main><aside className="space-y-5"><div className="card border-accent/50 bg-accent/10 p-5"><div className="mb-5 flex items-center justify-between"><div><div className="mono text-[10px] font-bold uppercase tracking-widest text-muted-foreground">Match signal</div><div className="mt-1 text-3xl font-bold">{job.score}<span className="text-base text-muted-foreground"> / 100</span></div></div><Sparkles className="text-amber-700" size={22} /></div><div className="space-y-3">{[['Role fit', breakdown.role], ['Skills', breakdown.skills], ['Experience', breakdown.experience], ['Location', breakdown.location], ['AI relevance', breakdown.aiRelevance], ['Freshness', breakdown.freshness]].map(([label, value]: any) => <div key={label}><div className="mb-1 flex justify-between text-xs"><span>{label}</span><span className="mono font-bold">{value ?? 0}</span></div><div className="h-1.5 rounded-full bg-primary/10"><div className="h-full rounded-full bg-primary" style={{ width: `${Math.min(100, value || 0)}%` }} /></div></div>)}</div></div><div className="card p-5"><h2 className="mb-4 font-bold">Transparent notes</h2><div className="mb-4"><div className="label">Matched skills</div><div className="flex flex-wrap gap-1.5">{(job.matchedSkills || []).length ? job.matchedSkills.map((skill: string) => <span className="rounded-md bg-emerald-100 px-2 py-1 text-xs font-medium text-emerald-800" key={skill}>{skill}</span>) : <span className="text-sm text-muted-foreground">No direct skill matches.</span>}</div></div><div><div className="label">Missing skills</div><div className="flex flex-wrap gap-1.5">{(job.missingSkills || []).length ? job.missingSkills.map((skill: string) => <span className="rounded-md bg-muted px-2 py-1 text-xs text-muted-foreground" key={skill}>{skill}</span>) : <span className="text-sm text-muted-foreground">No gaps flagged.</span>}</div></div></div><div className="card p-5 text-xs text-muted-foreground"><div className="mb-2 flex items-center gap-2 font-bold text-foreground"><Clock3 size={14} />Source timeline</div><div className="flex justify-between border-b border-border py-2"><span>Posted</span><span className="font-medium text-foreground">{formatDate(job.postedDate)}</span></div><div className="flex justify-between py-2"><span>Discovered</span><span className="font-medium text-foreground">{formatDate(job.firstSeenAt)}</span></div></div></aside></div></div>;
}

function Profile() {
  const q = useGetProfile(); const update = useUpdateProfile(); const qc = useQueryClient(); const profile: any = q.data; const [form, setForm] = useState<any>(null);
  const data = form || profile; if (q.isLoading) return <><PageTitle eyebrow="Tune / candidate profile" title="Candidate profile" detail="The baseline your matching engine reasons from." /><LoadingBlock lines={7} /></>; if (q.isError || !data) return <QueryError retry={() => q.refetch()} />;
  const patch = (key: string, value: any) => setForm({ ...data, [key]: value }); const save = () => update.mutate({ data: { ...data, ...form, roles: typeof data.roles === 'string' ? split(data.roles) : data.roles, skills: typeof data.skills === 'string' ? split(data.skills) : data.skills, technologies: typeof data.technologies === 'string' ? split(data.technologies) : data.technologies, locations: typeof data.locations === 'string' ? split(data.locations) : data.locations, includeKeywords: typeof data.includeKeywords === 'string' ? split(data.includeKeywords) : data.includeKeywords, excludeKeywords: typeof data.excludeKeywords === 'string' ? split(data.excludeKeywords) : data.excludeKeywords } }, { onSuccess: (next) => { setForm(null); qc.setQueryData(getGetProfileQueryKey(), next); } });
  const fields = [['roles', 'Target roles', 'Product design, UX research'], ['skills', 'Core skills', 'Research, prototyping, facilitation'], ['technologies', 'Tools & technologies', 'Figma, SQL, Notion'], ['locations', 'Preferred locations', 'New York, London, Remote'], ['includeKeywords', 'Include keywords', 'staff, platform, zero-to-one'], ['excludeKeywords', 'Exclude keywords', 'senior manager, contract']];
  return <div className="rise"><PageTitle eyebrow="Tune / candidate profile" title="Candidate profile" detail="The baseline your matching engine reasons from." action={<button className="btn btn-primary" onClick={save} disabled={!form || update.isPending} data-testid="button-save-profile"><Check size={15} />{update.isPending ? 'Saving…' : 'Save profile'}</button>} /><div className="grid gap-6 xl:grid-cols-[1.2fr_.8fr]"><div className="card p-5 sm:p-7"><div className="mb-6 border-b border-border pb-5"><div className="label">Contact</div><input className="field max-w-md" type="email" value={data.email || ''} onChange={(e) => patch('email', e.target.value)} placeholder="you@example.com" data-testid="input-profile-email" /></div><div className="grid gap-5 sm:grid-cols-2">{fields.map(([key, label, placeholder]) => <div key={key} className={key === 'includeKeywords' || key === 'excludeKeywords' ? '' : ''}><label className="label" htmlFor={`profile-${key}`}>{label}</label><input id={`profile-${key}`} className="field" value={join(data[key])} onChange={(e) => patch(key, e.target.value)} placeholder={placeholder} data-testid={`input-profile-${key}`} /><p className="mt-1.5 text-[10px] text-muted-foreground">Separate values with commas</p></div>)}</div></div><div className="space-y-5"><div className="card p-5"><div className="label">Experience window</div><div className="grid grid-cols-2 gap-3"><div><label className="mb-1 block text-xs text-muted-foreground">Minimum years</label><input className="field" type="number" min="0" value={data.minYears ?? 0} onChange={(e) => patch('minYears', Number(e.target.value))} data-testid="input-profile-min-years" /></div><div><label className="mb-1 block text-xs text-muted-foreground">Maximum years</label><input className="field" type="number" min="0" value={data.maxYears ?? 10} onChange={(e) => patch('maxYears', Number(e.target.value))} data-testid="input-profile-max-years" /></div></div></div><div className="card p-5"><div className="label">Workplace preference</div><div className="grid grid-cols-2 gap-2">{['Any', 'Remote', 'Hybrid', 'On-site'].map((value) => <button className={`rounded-lg border px-3 py-2 text-sm font-bold ${data.workplacePreference === value ? 'border-primary bg-primary text-primary-foreground' : 'border-border hover:bg-muted'}`} onClick={() => patch('workplacePreference', value)} key={value} data-testid={`button-workplace-${value}`}>{value}</button>)}</div></div><div className="rounded-xl border border-accent/50 bg-accent/10 p-5 text-sm"><div className="flex items-center gap-2 font-bold"><Sparkles size={16} className="text-amber-700" />A sharper profile, better signal</div><p className="mt-2 text-xs leading-relaxed text-muted-foreground">Keywords and workplace preference influence every score. Keep them specific enough to filter noise, broad enough to catch a good surprise.</p></div></div></div></div>;
}

function Matching() {
  const q = useGetMatchingConfiguration(); const update = useUpdateMatchingConfiguration(); const qc = useQueryClient(); const config: any = q.data; const [form, setForm] = useState<any>(null); if (q.isLoading) return <><PageTitle eyebrow="Tune / matching rules" title="Matching rules" detail="Decide what earns a closer look." /><LoadingBlock lines={5} /></>; if (q.isError || !config) return <QueryError retry={() => q.refetch()} />;
  const current = form || config; const set = (key: string, value: number) => setForm({ ...current, [key]: value }); const save = () => update.mutate({ data: current }, { onSuccess: (next) => { setForm(null); qc.setQueryData(getGetMatchingConfigurationQueryKey(), next); } }); const weights = [['roleWeight', 'Role fit', 'Title and role family alignment'], ['skillsWeight', 'Skills', 'Core skills and capabilities'], ['experienceWeight', 'Experience', 'Years and seniority fit'], ['locationWeight', 'Location', 'Place and workplace preference'], ['aiWeight', 'AI relevance', 'Semantic relevance across the role'], ['freshnessWeight', 'Freshness', 'Rewarding newly discovered roles']];
  return <div className="rise"><PageTitle eyebrow="Tune / matching rules" title="Matching rules" detail="Decide what earns a closer look." action={<button className="btn btn-primary" onClick={save} disabled={!form || update.isPending} data-testid="button-save-matching"><Check size={15} />{update.isPending ? 'Saving…' : 'Save rules'}</button>} /><div className="grid gap-6 xl:grid-cols-[1.1fr_.9fr]"><div className="card p-5 sm:p-7"><div className="mb-7 flex items-end justify-between border-b border-border pb-5"><div><div className="label">Match threshold</div><p className="text-sm text-muted-foreground">Only roles at or above this score become matches.</p></div><div className="mono text-3xl font-bold">{current.threshold}<span className="text-sm text-muted-foreground">%</span></div></div><input className="w-full accent-[hsl(var(--accent))]" type="range" min="0" max="100" value={current.threshold} onChange={(e) => set('threshold', Number(e.target.value))} data-testid="input-matching-threshold" /><div className="mt-2 flex justify-between text-[10px] text-muted-foreground"><span>Broad net</span><span>Focused signal</span></div><div className="mt-8 space-y-5">{weights.map(([key, label, hint]) => <div key={key}><div className="mb-2 flex items-center justify-between"><div><div className="text-sm font-bold">{label}</div><div className="text-[11px] text-muted-foreground">{hint}</div></div><div className="mono text-sm font-bold">{current[key]}%</div></div><input className="w-full accent-[hsl(var(--primary))]" type="range" min="0" max="100" value={current[key]} onChange={(e) => set(key, Number(e.target.value))} data-testid={`input-matching-${key}`} /></div>)}</div></div><aside className="space-y-5"><div className="card overflow-hidden"><div className="border-b border-border px-5 py-4"><h2 className="font-bold">How the score reads</h2><p className="mt-1 text-xs text-muted-foreground">A simple, inspectable model.</p></div><div className="p-5"><div className="flex items-center gap-3"><div className="mono flex h-16 w-16 items-center justify-center rounded-2xl bg-accent text-2xl font-bold text-primary">{current.threshold}</div><div><div className="font-bold">Your floor</div><div className="text-xs leading-relaxed text-muted-foreground">A role must clear this line before it appears as a match.</div></div></div><div className="my-5 border-t border-border" /><div className="space-y-3 text-xs"><div className="flex items-center gap-2"><CircleCheck size={14} className="text-emerald-700" /><span>Matched roles surface in Overview</span></div><div className="flex items-center gap-2"><Mail size={14} className="text-amber-700" /><span>Notifications follow matched roles</span></div><div className="flex items-center gap-2"><Eye size={14} className="text-muted-foreground" /><span>Every score stays transparent</span></div></div></div></div><div className="rounded-xl bg-primary p-5 text-primary-foreground"><div className="mono text-[10px] uppercase tracking-widest text-primary-foreground/50">Current posture</div><div className="mt-2 text-lg font-bold">{current.threshold >= 75 ? 'Focused' : current.threshold >= 55 ? 'Balanced' : 'Exploratory'}</div><p className="mt-1 text-xs leading-relaxed text-primary-foreground/60">You’re currently favoring {current.roleWeight >= current.skillsWeight ? 'role alignment' : 'skills evidence'} in the first pass.</p></div></aside></div></div>;
}

function Notifications() {
  const q = useListNotifications(); const notices: any[] = q.data || []; return <div className="rise"><PageTitle eyebrow="Tune / notifications" title="Notification history" detail="A record of every signal sent to your inbox." action={<Link href="/profile" className="btn btn-ghost" data-testid="link-notification-preferences"><Settings2 size={15} />Notification settings</Link>} />{q.isLoading ? <LoadingBlock lines={6} /> : q.isError ? <QueryError retry={() => q.refetch()} /> : !notices.length ? <EmptyState title="No notifications sent" detail="When a role clears your matching threshold, it will appear here." /> : <div className="card overflow-hidden"><div className="hidden grid-cols-[1.4fr_1fr_.65fr_.8fr] gap-4 border-b border-border bg-muted/40 px-5 py-3 text-[10px] font-bold uppercase tracking-wider text-muted-foreground sm:grid"><span>Role</span><span>Sent</span><span>Score</span><span>Status</span></div>{notices.map((n) => <div className="grid gap-2 border-b border-border px-5 py-4 last:border-0 sm:grid-cols-[1.4fr_1fr_.65fr_.8fr] sm:items-center sm:gap-4" key={n.id} data-testid={`row-notification-${n.id}`}><div><div className="text-sm font-bold">{n.jobTitle}</div><div className="mt-0.5 text-xs text-muted-foreground">{n.company} · {n.type}</div></div><div className="text-xs text-muted-foreground">{formatDate(n.sentAt)}</div><div><Score score={n.score} compact /></div><div><StatusPill status={n.status} />{n.error && <div className="mt-1 text-[10px] text-destructive">{n.error}</div>}</div></div>)}</div>}</div>;
}

function Router() {
  const [location] = useLocation();
  return <ErrorBoundary resetKey={location}><Layout><Switch><Route path="/" component={Dashboard} /><Route path="/companies" component={Companies} /><Route path="/sources" component={() => <Sources />} /><Route path="/jobs" component={Jobs} /><Route path="/jobs/:id" component={JobDetail} /><Route path="/profile" component={Profile} /><Route path="/matching" component={Matching} /><Route path="/notifications" component={Notifications} /><Route path="/source-health" component={() => <Sources healthOnly />} /><Route component={NotFound} /></Switch></Layout></ErrorBoundary>;
}
function App() {
  return <QueryClientProvider client={queryClient}><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><Router /></WouterRouter><Toaster /></TooltipProvider></QueryClientProvider>;
}
export default App;
